let file = """{"version":3,"file":"CancellationFlowDialogContent-BJkFKUIj.js","names":["$t","$t"],"sources":["../../src/platform/cloud/subscription/utils/cancellationSurvey.ts","../../src/platform/cloud/subscription/components/CancellationSurveyStep.vue","../../src/platform/cloud/subscription/components/CancellationSurveyStep.vue","../../src/platform/cloud/subscription/utils/retentionOffer.ts","../../src/platform/cloud/subscription/composables/useRetentionOffer.ts","../../src/platform/cloud/subscription/components/RetentionOfferStep.vue","../../src/platform/cloud/subscription/components/RetentionOfferStep.vue","../../src/platform/cloud/subscription/components/CancellationFlowDialogContent.vue","../../src/platform/cloud/subscription/components/CancellationFlowDialogContent.vue"],"sourcesContent":["import type {\n  InAppSurveyEvent,\n  InAppSurveyStage\n} from '@/platform/telemetry/types'\n\nexport const CANCELLATION_REASONS = [\n  'tooExpensive',\n  'notUsingEnough',\n  'missingFeatures',\n  'switchingTools',\n  'somethingElse'\n] as const\n\nexport type CancellationReason = (typeof CANCELLATION_REASONS)[number]\n\nexport type CancellationSurveyExit =\n  | 'continue_cancelling'\n  | 'keep_plan'\n  | 'closed'\n\nexport interface CancellationSurveyAnswers {\n  reason?: CancellationReason\n  comment: string\n}\n\nconst REASON_QUESTION_ID = 'f5b2934c-a2aa-4e9d-83d2-bbb346b2a196'\nconst COMMENT_QUESTION_ID = '3a3166fb-c479-439b-8c8a-65dde9f2147a'\n\nconst REASON_CHOICES: Record<CancellationReason, string> = {\n  tooExpensive: 'Too expensive',\n  notUsingEnough: 'Not using it enough',\n  missingFeatures: 'Missing features or models',\n  switchingTools: 'Switching to another tool',\n  somethingElse: 'Something else'\n}\n\nfunction surveyResponses({\n  reason,\n  comment\n}: CancellationSurveyAnswers): Record<string, string> {\n  const responses: Record<string, string> = {}\n  if (reason) responses[REASON_QUESTION_ID] = REASON_CHOICES[reason]\n  const trimmedComment = comment.trim()\n  if (trimmedComment) responses[COMMENT_QUESTION_ID] = trimmedComment\n  return responses\n}\n\nfunction experimentProperties(\n  experimentVariant: string | undefined\n): Record<string, string> {\n  return experimentVariant ? { experiment_variant: experimentVariant } : {}\n}\n\nexport function cancellationSurveyShownEvent(options: {\n  surveyId: string\n  experimentVariant?: string\n}): InAppSurveyEvent {\n  return {\n    surveyId: options.surveyId,\n    properties: experimentProperties(options.experimentVariant)\n  }\n}\n\nexport function cancellationSurveyExitEvent(options: {\n  surveyId: string\n  answers: CancellationSurveyAnswers\n  exit: CancellationSurveyExit\n  experimentVariant?: string\n}): { stage: InAppSurveyStage; event: InAppSurveyEvent } {\n  const responses = surveyResponses(options.answers)\n  const properties = {\n    outcome: options.exit,\n    ...experimentProperties(options.experimentVariant)\n  }\n  if (Object.keys(responses).length === 0)\n    return {\n      stage: 'dismissed',\n      event: { surveyId: options.surveyId, properties }\n    }\n  return {\n    stage: 'sent',\n    event: { surveyId: options.surveyId, responses, properties }\n  }\n}\n","<template>\n  <CancellationStepLayout\n    :title=\"$t('subscription.cancelFlow.survey.title')\"\n    :subtitle=\"$t('subscription.cancelFlow.survey.subtitle')\"\n    :on-close=\"() => exit('closed')\"\n  >\n    <div class=\"flex flex-col gap-6\">\n      <RadioGroupRoot\n        :model-value=\"reason\"\n        :aria-label=\"$t('subscription.cancelFlow.survey.title')\"\n        class=\"flex flex-col gap-2\"\n        @update:model-value=\"selectReason\"\n      >\n        <RadioGroupItem\n          v-for=\"option in CANCELLATION_REASONS\"\n          :key=\"option\"\n          :value=\"option\"\n          :class=\"\n            cn(\n              'flex w-full cursor-pointer items-center gap-2 rounded-[10px] border border-border-subtle bg-transparent p-2.5 text-left text-sm text-base-foreground transition-colors hover:bg-secondary-background-hover focus-visible:ring-1 focus-visible:ring-border-default focus-visible:outline-none',\n              reason === option && 'border-transparent bg-secondary-background'\n            )\n          \"\n        >\n          <span\n            :class=\"\n              cn(\n                'flex size-4 shrink-0 items-center justify-center rounded-full border border-border-subtle',\n                reason === option && 'border-base-foreground bg-base-foreground'\n              )\n            \"\n            aria-hidden=\"true\"\n          >\n            <span\n              v-if=\"reason === option\"\n              class=\"size-2 rounded-full bg-base-background\"\n            />\n          </span>\n          {{ $t(`subscription.cancelFlow.survey.reasons.${option}`) }}\n        </RadioGroupItem>\n      </RadioGroupRoot>\n\n      <div class=\"flex flex-col gap-3\">\n        <label :for=\"commentId\" class=\"text-sm text-base-foreground\">\n          {{ $t('subscription.cancelFlow.survey.commentLabel') }}\n        </label>\n        <Textarea\n          :id=\"commentId\"\n          v-model=\"comment\"\n          class=\"h-24 resize-none font-inter\"\n          :placeholder=\"$t('subscription.cancelFlow.survey.commentPlaceholder')\"\n          maxlength=\"2000\"\n        />\n      </div>\n    </div>\n\n    <template #actions>\n      <Button variant=\"textonly\" size=\"lg\" @click=\"exit('keep_plan')\">\n        {{ $t('subscription.cancelFlow.keepPlan') }}\n      </Button>\n      <Button\n        variant=\"secondary\"\n        size=\"lg\"\n        @click=\"exit('continue_cancelling')\"\n      >\n        {{ $t('subscription.cancelFlow.continueCancelling') }}\n      </Button>\n    </template>\n  </CancellationStepLayout>\n</template>\n\n<script setup lang=\"ts\">\nimport { RadioGroupItem, RadioGroupRoot } from 'reka-ui'\nimport { onMounted, ref, useId } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Textarea from '@/components/ui/textarea/Textarea.vue'\nimport CancellationStepLayout from '@/platform/cloud/subscription/components/CancellationStepLayout.vue'\nimport type {\n  CancellationReason,\n  CancellationSurveyExit\n} from '@/platform/cloud/subscription/utils/cancellationSurvey'\nimport {\n  CANCELLATION_REASONS,\n  cancellationSurveyExitEvent,\n  cancellationSurveyShownEvent\n} from '@/platform/cloud/subscription/utils/cancellationSurvey'\nimport { useTelemetry } from '@/platform/telemetry'\n\nconst { surveyId, experimentVariant, onExit } = defineProps<{\n  surveyId: string\n  experimentVariant?: string\n  onExit: (exit: CancellationSurveyExit) => void\n}>()\n\nconst telemetry = useTelemetry()\nconst reason = ref<CancellationReason>()\nconst comment = ref('')\nconst commentId = useId()\n\nonMounted(() => {\n  telemetry?.trackInAppSurvey(\n    'shown',\n    cancellationSurveyShownEvent({ surveyId, experimentVariant })\n  )\n})\n\nfunction selectReason(value: unknown) {\n  reason.value = CANCELLATION_REASONS.find((option) => option === value)\n}\n\nfunction exit(choice: CancellationSurveyExit) {\n  const { stage, event } = cancellationSurveyExitEvent({\n    surveyId,\n    answers: { reason: reason.value, comment: comment.value },\n    exit: choice,\n    experimentVariant\n  })\n  telemetry?.trackInAppSurvey(stage, event)\n  onExit(choice)\n}\n</script>\n","<template>\n  <CancellationStepLayout\n    :title=\"$t('subscription.cancelFlow.survey.title')\"\n    :subtitle=\"$t('subscription.cancelFlow.survey.subtitle')\"\n    :on-close=\"() => exit('closed')\"\n  >\n    <div class=\"flex flex-col gap-6\">\n      <RadioGroupRoot\n        :model-value=\"reason\"\n        :aria-label=\"$t('subscription.cancelFlow.survey.title')\"\n        class=\"flex flex-col gap-2\"\n        @update:model-value=\"selectReason\"\n      >\n        <RadioGroupItem\n          v-for=\"option in CANCELLATION_REASONS\"\n          :key=\"option\"\n          :value=\"option\"\n          :class=\"\n            cn(\n              'flex w-full cursor-pointer items-center gap-2 rounded-[10px] border border-border-subtle bg-transparent p-2.5 text-left text-sm text-base-foreground transition-colors hover:bg-secondary-background-hover focus-visible:ring-1 focus-visible:ring-border-default focus-visible:outline-none',\n              reason === option && 'border-transparent bg-secondary-background'\n            )\n          \"\n        >\n          <span\n            :class=\"\n              cn(\n                'flex size-4 shrink-0 items-center justify-center rounded-full border border-border-subtle',\n                reason === option && 'border-base-foreground bg-base-foreground'\n              )\n            \"\n            aria-hidden=\"true\"\n          >\n            <span\n              v-if=\"reason === option\"\n              class=\"size-2 rounded-full bg-base-background\"\n            />\n          </span>\n          {{ $t(`subscription.cancelFlow.survey.reasons.${option}`) }}\n        </RadioGroupItem>\n      </RadioGroupRoot>\n\n      <div class=\"flex flex-col gap-3\">\n        <label :for=\"commentId\" class=\"text-sm text-base-foreground\">\n          {{ $t('subscription.cancelFlow.survey.commentLabel') }}\n        </label>\n        <Textarea\n          :id=\"commentId\"\n          v-model=\"comment\"\n          class=\"h-24 resize-none font-inter\"\n          :placeholder=\"$t('subscription.cancelFlow.survey.commentPlaceholder')\"\n          maxlength=\"2000\"\n        />\n      </div>\n    </div>\n\n    <template #actions>\n      <Button variant=\"textonly\" size=\"lg\" @click=\"exit('keep_plan')\">\n        {{ $t('subscription.cancelFlow.keepPlan') }}\n      </Button>\n      <Button\n        variant=\"secondary\"\n        size=\"lg\"\n        @click=\"exit('continue_cancelling')\"\n      >\n        {{ $t('subscription.cancelFlow.continueCancelling') }}\n      </Button>\n    </template>\n  </CancellationStepLayout>\n</template>\n\n<script setup lang=\"ts\">\nimport { RadioGroupItem, RadioGroupRoot } from 'reka-ui'\nimport { onMounted, ref, useId } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Textarea from '@/components/ui/textarea/Textarea.vue'\nimport CancellationStepLayout from '@/platform/cloud/subscription/components/CancellationStepLayout.vue'\nimport type {\n  CancellationReason,\n  CancellationSurveyExit\n} from '@/platform/cloud/subscription/utils/cancellationSurvey'\nimport {\n  CANCELLATION_REASONS,\n  cancellationSurveyExitEvent,\n  cancellationSurveyShownEvent\n} from '@/platform/cloud/subscription/utils/cancellationSurvey'\nimport { useTelemetry } from '@/platform/telemetry'\n\nconst { surveyId, experimentVariant, onExit } = defineProps<{\n  surveyId: string\n  experimentVariant?: string\n  onExit: (exit: CancellationSurveyExit) => void\n}>()\n\nconst telemetry = useTelemetry()\nconst reason = ref<CancellationReason>()\nconst comment = ref('')\nconst commentId = useId()\n\nonMounted(() => {\n  telemetry?.trackInAppSurvey(\n    'shown',\n    cancellationSurveyShownEvent({ surveyId, experimentVariant })\n  )\n})\n\nfunction selectReason(value: unknown) {\n  reason.value = CANCELLATION_REASONS.find((option) => option === value)\n}\n\nfunction exit(choice: CancellationSurveyExit) {\n  const { stage, event } = cancellationSurveyExitEvent({\n    surveyId,\n    answers: { reason: reason.value, comment: comment.value },\n    exit: choice,\n    experimentVariant\n  })\n  telemetry?.trackInAppSurvey(stage, event)\n  onExit(choice)\n}\n</script>\n","import type { RetentionOffer } from '@comfyorg/ingest-types'\n\nexport type RetentionOfferPhase =\n  | 'offered'\n  | 'accepting'\n  | 'applied'\n  | 'failed'\n  | 'declined'\n  | 'expired'\n  | 'unconfirmed'\n\nexport type RetentionOfferEvent =\n  | { type: 'acceptRequested' }\n  | { type: 'applied' }\n  | { type: 'rejected' }\n  | { type: 'declined' }\n  | { type: 'expired' }\n  | { type: 'unconfirmed' }\n\nexport type RetentionOfferOutcome =\n  | 'retained'\n  | 'continueToCancel'\n  | 'pending'\n  | 'dismissed'\n\nexport function reduceRetentionOffer(\n  phase: RetentionOfferPhase,\n  event: RetentionOfferEvent\n): RetentionOfferPhase {\n  switch (event.type) {\n    case 'acceptRequested':\n      return phase === 'offered' ||\n        phase === 'failed' ||\n        phase === 'unconfirmed'\n        ? 'accepting'\n        : phase\n    case 'applied':\n      return phase === 'accepting' ? 'applied' : phase\n    case 'rejected':\n      return phase === 'accepting' ? 'failed' : phase\n    case 'declined':\n      return phase === 'accepting' ? 'declined' : phase\n    case 'expired':\n      return phase === 'offered' || phase === 'accepting' ? 'expired' : phase\n    case 'unconfirmed':\n      return phase === 'accepting' ? 'unconfirmed' : phase\n  }\n}\n\nexport function outcomeOnClose(\n  phase: RetentionOfferPhase\n): RetentionOfferOutcome {\n  switch (phase) {\n    case 'applied':\n      return 'retained'\n    case 'accepting':\n    case 'unconfirmed':\n      return 'pending'\n    case 'offered':\n    case 'failed':\n    case 'declined':\n    case 'expired':\n      return 'dismissed'\n  }\n}\n\nexport function discountedAmount(\n  amount: number,\n  offer: Pick<RetentionOffer, 'percent_off'>\n): number {\n  return Math.round((amount * (100 - offer.percent_off)) / 100)\n}\n\nexport function fullPriceRenewal(periodEnd: number, months: number): Date {\n  const start = new Date(periodEnd * 1000)\n  const renewal = new Date(start)\n  renewal.setUTCDate(1)\n  renewal.setUTCMonth(start.getUTCMonth() + months)\n  const lastDayOfMonth = new Date(\n    Date.UTC(renewal.getUTCFullYear(), renewal.getUTCMonth() + 1, 0)\n  ).getUTCDate()\n  renewal.setUTCDate(Math.min(start.getUTCDate(), lastDayOfMonth))\n  return renewal\n}\n","import { readonly, shallowRef } from 'vue'\n\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { t } from '@/i18n'\nimport { recordRetentionFlowEvent } from '@/platform/cloud/subscription/launchCancellationFlow'\nimport type {\n  RetentionOfferEvent,\n  RetentionOfferPhase\n} from '@/platform/cloud/subscription/utils/retentionOffer'\nimport { reduceRetentionOffer } from '@/platform/cloud/subscription/utils/retentionOffer'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { workspaceApi } from '@/platform/workspace/api/workspaceApi'\nimport { WorkspaceApiError } from '@/platform/workspace/api/workspaceApiError'\nimport { useBillingOperationStore } from '@/platform/workspace/stores/billingOperationStore'\n\ntype RedemptionResult = Exclude<\n  RetentionOfferEvent,\n  { type: 'acceptRequested' }\n>\n\nfunction refusal(error: unknown): RedemptionResult | undefined {\n  if (!(error instanceof WorkspaceApiError) || error.status === undefined) {\n    return undefined\n  }\n  if (error.status >= 500 && error.status !== 503) return undefined\n  switch (error.code) {\n    case 'RETENTION_SESSION_STALE':\n    case 'RETENTION_ALREADY_REDEEMED':\n      return { type: 'expired' }\n    case 'PREVIOUS_OPERATION_FAILED':\n    case 'RETENTION_NOT_ALLOWED':\n      return { type: 'declined' }\n    default:\n      return { type: 'rejected' }\n  }\n}\n\nasync function redeem(\n  sessionId: string,\n  workspaceId: string\n): Promise<RedemptionResult> {\n  try {\n    const acceptance = await workspaceApi.acceptRetentionOffer(sessionId)\n    if (acceptance.status === 'succeeded') return { type: 'applied' }\n    const operation = await useBillingOperationStore().startOperation(\n      acceptance.billing_op_id,\n      'retention',\n      { workspaceId }\n    )\n    switch (operation.status) {\n      case 'succeeded':\n        return { type: 'applied' }\n      case 'failed':\n        return { type: 'declined' }\n      default:\n        return { type: 'unconfirmed' }\n    }\n  } catch (error) {\n    const refused = refusal(error)\n    if (refused) return refused\n    reportError(error, {\n      surface: 'billing',\n      errorType: 'failure_confirming_retention_offer'\n    })\n    return { type: 'unconfirmed' }\n  }\n}\n\nexport function useRetentionOffer(sessionId: string, workspaceId: string) {\n  const { fetchStatus } = useBillingContext()\n  const phase = shallowRef<RetentionOfferPhase>('offered')\n\n  function dispatch(event: RetentionOfferEvent) {\n    phase.value = reduceRetentionOffer(phase.value, event)\n  }\n\n  async function refreshPlan() {\n    try {\n      await fetchStatus()\n    } catch (error) {\n      reportError(error, {\n        surface: 'billing',\n        errorType: 'error_refreshing_billing_after_retention_discount'\n      })\n      useToast().warning(t('subscription.retentionOffer.refreshFailed'), {\n        duration: 8000\n      })\n    }\n  }\n\n  async function recordShown() {\n    const recorded = await recordRetentionFlowEvent(sessionId, 'offer_shown')\n    if (recorded === 'expired') dispatch({ type: 'expired' })\n  }\n\n  async function accept() {\n    const requested = reduceRetentionOffer(phase.value, {\n      type: 'acceptRequested'\n    })\n    if (requested === phase.value) return\n    phase.value = requested\n    const result = await redeem(sessionId, workspaceId)\n    dispatch(result)\n    if (result.type === 'applied') await refreshPlan()\n  }\n\n  return { phase: readonly(phase), accept, recordShown }\n}\n","<template>\n  <CancellationStepLayout\n    :title=\"heading.title\"\n    :subtitle=\"heading.subtitle\"\n    :close-disabled=\"phase === 'accepting'\"\n    :on-close=\"close\"\n  >\n    <template v-if=\"phase === 'applied'\" #title-icon>\n      <i\n        class=\"icon-[lucide--circle-check-big] size-6 text-success-background\"\n        aria-hidden=\"true\"\n      />\n    </template>\n\n    <div\n      v-if=\"phase === 'offered' || phase === 'accepting'\"\n      class=\"flex flex-col gap-3\"\n    >\n      <div\n        class=\"flex flex-col gap-3 rounded-[14px] border border-border-subtle bg-secondary-background/50 px-4 py-5 shadow-xs\"\n      >\n        <div class=\"flex items-center justify-between gap-2\">\n          <p class=\"m-0 text-sm font-medium text-base-foreground\">\n            {{\n              $t('subscription.retentionOffer.stayOnPlan', { plan: planName })\n            }}\n          </p>\n          <Badge\n            variant=\"compact\"\n            class=\"bg-base-foreground text-base-background\"\n          >\n            {{ $t('subscription.retentionOffer.percentOff', { percent }) }}\n          </Badge>\n        </div>\n        <p class=\"m-0 flex flex-wrap items-baseline gap-1.5\">\n          <span\n            class=\"text-[32px] leading-[1.15] font-semibold text-base-foreground\"\n          >\n            {{ discountedPrice }}\n          </span>\n          <span class=\"text-sm text-muted-foreground\">\n            {{ $t('subscription.retentionOffer.perMonth') }}\n          </span>\n          <span class=\"text-sm text-muted-foreground line-through\">\n            {{ regularPrice }}\n          </span>\n        </p>\n        <p class=\"m-0 text-sm text-muted-foreground\">\n          {{\n            $t(\n              'subscription.retentionOffer.term',\n              { regular: regularPrice, months },\n              months\n            )\n          }}\n        </p>\n        <div class=\"h-px bg-border-subtle\" role=\"presentation\" />\n        <p class=\"m-0 text-sm text-muted-foreground\">{{ keepMessage }}</p>\n      </div>\n      <p class=\"m-0 text-sm text-muted-foreground\">\n        {{\n          $t(\n            'subscription.retentionOffer.finePrint',\n            { plan: planName, regular: regularPrice, months },\n            months\n          )\n        }}\n      </p>\n    </div>\n\n    <div v-else-if=\"phase === 'applied'\" class=\"flex flex-col gap-5\">\n      <div\n        class=\"flex flex-col gap-3 rounded-[14px] border border-border-subtle bg-secondary-background/50 p-4 shadow-xs\"\n      >\n        <div class=\"flex flex-wrap items-center justify-between gap-2 text-sm\">\n          <span class=\"flex items-center gap-2 text-base-foreground\">\n            {{\n              $t('subscription.retentionOffer.nextPayments', { months }, months)\n            }}\n            <Badge\n              variant=\"compact\"\n              class=\"bg-base-foreground text-base-background\"\n            >\n              {{ $t('subscription.retentionOffer.appliedBadge') }}\n            </Badge>\n          </span>\n          <span class=\"flex items-center gap-2\">\n            <span class=\"text-muted-foreground line-through\">\n              {{ regularAmount }}\n            </span>\n            <span class=\"text-base-foreground\">\n              {{\n                $t('subscription.retentionOffer.pricePerMonth', {\n                  price: discountedMonthlyAmount\n                })\n              }}\n            </span>\n          </span>\n        </div>\n        <p class=\"m-0 text-sm text-muted-foreground\">\n          {{\n            $t(\n              'subscription.retentionOffer.savings',\n              { savings, months },\n              months\n            )\n          }}\n        </p>\n      </div>\n      <p class=\"m-0 text-sm text-muted-foreground\">\n        {{\n          $t('subscription.retentionOffer.renewsAt', {\n            regular: regularAmount,\n            date: fullPriceDate\n          })\n        }}\n      </p>\n    </div>\n\n    <p\n      v-else-if=\"phase === 'failed' || phase === 'declined'\"\n      class=\"m-0 text-xs/5 text-muted-foreground\"\n    >\n      {{ $t('subscription.retentionOffer.supportCode') }}\n    </p>\n\n    <template #actions>\n      <template v-if=\"phase === 'offered' || phase === 'accepting'\">\n        <Button\n          variant=\"inverted\"\n          size=\"lg\"\n          :loading=\"phase === 'accepting'\"\n          @click=\"acceptOffer\"\n        >\n          {{\n            $t('subscription.retentionOffer.accept', {\n              plan: planName,\n              percent\n            })\n          }}\n        </Button>\n        <Button\n          variant=\"secondary\"\n          size=\"lg\"\n          :disabled=\"phase === 'accepting'\"\n          @click=\"onDecide('continueToCancel')\"\n        >\n          {{ $t('subscription.cancelFlow.continueCancelling') }}\n        </Button>\n      </template>\n      <template v-else-if=\"phase === 'failed'\">\n        <Button variant=\"inverted\" size=\"lg\" @click=\"acceptOffer\">\n          {{ $t('subscription.retentionOffer.tryAgain') }}\n        </Button>\n        <Button\n          variant=\"secondary\"\n          size=\"lg\"\n          @click=\"onDecide('continueToCancel')\"\n        >\n          {{ $t('subscription.cancelFlow.continueCancelling') }}\n        </Button>\n      </template>\n      <template v-else-if=\"phase === 'declined' || phase === 'expired'\">\n        <Button variant=\"textonly\" size=\"lg\" @click=\"close\">\n          {{ $t('subscription.cancelFlow.keepPlan') }}\n        </Button>\n        <Button\n          variant=\"secondary\"\n          size=\"lg\"\n          @click=\"onDecide('continueToCancel')\"\n        >\n          {{ $t('subscription.cancelFlow.continueCancelling') }}\n        </Button>\n      </template>\n      <template v-else-if=\"phase === 'unconfirmed'\">\n        <Button variant=\"inverted\" size=\"lg\" @click=\"acceptOffer\">\n          {{ $t('subscription.retentionOffer.checkAgain') }}\n        </Button>\n        <Button variant=\"secondary\" size=\"lg\" @click=\"close\">\n          {{ $t('g.close') }}\n        </Button>\n      </template>\n      <Button v-else variant=\"secondary\" size=\"lg\" class=\"w-24\" @click=\"close\">\n        {{ $t('subscription.cancelFlow.done') }}\n      </Button>\n    </template>\n  </CancellationStepLayout>\n</template>\n\n<script setup lang=\"ts\">\nimport { formatQuoteMoney } from '@comfyorg/account-ui/billing/checkout'\nimport type {\n  RetentionFlowSubscription,\n  RetentionOffer\n} from '@comfyorg/ingest-types'\nimport { computed, onMounted } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Badge from '@/components/ui/badge/Badge.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport CancellationStepLayout from '@/platform/cloud/subscription/components/CancellationStepLayout.vue'\nimport { useCancellationPlan } from '@/platform/cloud/subscription/composables/useCancellationPlan'\nimport { useRetentionOffer } from '@/platform/cloud/subscription/composables/useRetentionOffer'\nimport type {\n  RetentionOfferOutcome,\n  RetentionOfferPhase\n} from '@/platform/cloud/subscription/utils/retentionOffer'\nimport {\n  discountedAmount,\n  fullPriceRenewal,\n  outcomeOnClose\n} from '@/platform/cloud/subscription/utils/retentionOffer'\nimport { formatCurrencyCents } from '@/utils/numberUtil'\n\nconst {\n  offer,\n  subscription,\n  sessionId,\n  workspaceId,\n  isScopeCurrent,\n  onDecide\n} = defineProps<{\n  offer: RetentionOffer\n  subscription: RetentionFlowSubscription\n  sessionId: string\n  workspaceId: string\n  isScopeCurrent: () => boolean\n  onDecide: (outcome: RetentionOfferOutcome) => void\n}>()\n\nconst { t, n, locale } = useI18n()\nconst { planName, creditGrant, includesCustomLoRAs } = useCancellationPlan()\nconst { phase, accept, recordShown } = useRetentionOffer(sessionId, workspaceId)\n\nconst percent = offer.percent_off\nconst months = offer.duration_in_months\nconst monthlyAmount = subscription.unit_amount * subscription.quantity\nconst discountedMonthly = discountedAmount(monthlyAmount, offer)\n\nfunction headlinePrice(cents: number) {\n  return formatCurrencyCents(locale.value, cents, subscription.currency)\n}\n\nfunction exactAmount(cents: number) {\n  return formatQuoteMoney(cents, subscription.currency, locale.value)\n}\n\nfunction formatDate(date: Date) {\n  return date.toLocaleDateString(locale.value, {\n    month: 'long',\n    day: 'numeric',\n    year: 'numeric'\n  })\n}\n\nconst regularPrice = computed(() => headlinePrice(monthlyAmount))\nconst discountedPrice = computed(() => headlinePrice(discountedMonthly))\nconst regularAmount = computed(() => exactAmount(monthlyAmount))\nconst discountedMonthlyAmount = computed(() => exactAmount(discountedMonthly))\nconst savings = computed(() =>\n  exactAmount((monthlyAmount - discountedMonthly) * months)\n)\nconst discountStartDate = computed(() =>\n  formatDate(new Date(subscription.period_end * 1000))\n)\nconst fullPriceDate = computed(() =>\n  formatDate(fullPriceRenewal(subscription.period_end, months))\n)\n\nconst keepMessage = computed(() => {\n  const grant = creditGrant.value\n  if (grant?.cycle !== 'monthly')\n    return t('subscription.retentionOffer.keepEverything', {\n      plan: planName.value\n    })\n  const named = { credits: n(grant.credits), plan: planName.value }\n  return includesCustomLoRAs.value\n    ? t('subscription.retentionOffer.keepCreditsAndLoRAs', named)\n    : t('subscription.retentionOffer.keepCredits', named)\n})\n\nconst heading = computed(() => {\n  const offered = {\n    title: t('subscription.retentionOffer.title'),\n    subtitle: t('subscription.retentionOffer.subtitle')\n  }\n  const headings: Record<\n    RetentionOfferPhase,\n    { title: string; subtitle: string }\n  > = {\n    offered,\n    accepting: offered,\n    applied: {\n      title: t('subscription.retentionOffer.appliedTitle', {\n        plan: planName.value\n      }),\n      subtitle: t(\n        'subscription.retentionOffer.appliedBody',\n        { percent, months, date: discountStartDate.value },\n        months\n      )\n    },\n    failed: {\n      title: t('subscription.retentionOffer.failedTitle'),\n      subtitle: t('subscription.retentionOffer.failedBody', {\n        plan: planName.value\n      })\n    },\n    declined: {\n      